#include <iostream>
#include <iomanip>

int main() {
    // Minh hoa sai so float
    float fMoney = 1000000.00f;
    fMoney += 0.12f;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Float: " << fMoney << "\n"; // Mat do chinh xac

    // Tinh toan chinh xac bang so nguyen (cents)
    long long intMoney = 100000000LL; // 1,000,000.00 dollars = 100,000,000 cents
    intMoney += 12LL; // + 12 cents
    std::cout << "Integer: " << (intMoney / 100) << "." 
              << std::setfill('0') << std::setw(2) << (intMoney % 100) << "\n";

    // Vong lap khong dung break (structured exit flag)
    int counter = 1;
    bool found = false;
    while (counter <= 10 && !found) {
        if (counter == 5) {
            found = true; // Thoat vong lap co cau truc
        } else {
            ++counter;
        }
    }
    std::cout << "Stopped at: " << counter << "\n";
    return 0;
}
